   * @param {nsIMsgAccount} account - The email account created.
   */
  setState(account) {
    this.#account = account;
  }

  handleEvent(event) {
    switch (event.type) {
      case "click":
        window.MsgAccountManager(
          event.target.id === "accountHubEncryptionLink"
            ? "am-e2e.xhtml"
            : null,
          this.#account?.incomingServer
        );
        break;
    }
  }
}
